import{_ as a,C as i,o as n,c as r,E as s,a2 as l}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Research Runtime Scheduler V1.0","description":"The first formal release record of Research Runtime Scheduler; the current operating baseline is Scheduler V2.0 and Runtime Center V4.","frontmatter":{"title":"Research Runtime Scheduler V1.0","description":"The first formal release record of Research Runtime Scheduler; the current operating baseline is Scheduler V2.0 and Runtime Center V4.","outline":"deep"},"headers":[],"relativePath":"en/publications/research-runtime-scheduler-v1.0.md","filePath":"en/publications/research-runtime-scheduler-v1.0.md","lastUpdated":1785829946000}'),o={name:"en/publications/research-runtime-scheduler-v1.0.md"};function c(d,e,u,h,p,m){const t=i("ArticleCover");return n(),r("div",null,[s(t,{image:"/assets/covers/research-runtime-scheduler-v1.svg",kicker:"Digital Employee Works · Historical Runtime Release",title:"Research Runtime Scheduler V1.0",summary:"The first formal scheduler and operational control-plane release of the Research Operating System.",version:"V1.0",status:"Released 2026-08-02 · Historical Release",languageHref:"/zh/publications/research-runtime-scheduler-v1.0",languageLabel:"简体中文"}),e[0]||(e[0]=l(`<div class="info custom-block"><p class="custom-block-title">Current operating baseline</p><p>The current formal operating system has advanced to:</p><ul><li><strong>Research Runtime Center V4</strong>;</li><li><strong>Research Runtime Scheduler V2.0</strong>;</li><li><strong>Research Report Production Engine V1.3</strong>;</li><li><strong>Research Intelligence System V1.0</strong>;</li><li>eight formal Runtime tasks, including daily Production at 15:00;</li><li>release-only Publication at 20:00 for complete candidates.</li></ul><p><a href="/joinwell52/en/runtime/v4">Read the current V4 Runtime specification →</a><br><a href="./research-report-production-engine-v1.3">Read Research Report Production Engine V1.3 →</a></p></div><h2 id="historical-significance-of-v1-0" tabindex="-1">Historical significance of V1.0 <a class="header-anchor" href="#historical-significance-of-v1-0" aria-label="Permalink to &quot;Historical significance of V1.0&quot;">​</a></h2><p>Research Runtime Scheduler V1.0 first established Research Runtime Center as the formal operational control plane of the Research Operating System.</p><p>It established these principles:</p><ul><li>Research Runtime—not an individual automation task—is the Digital Researcher’s operational control plane;</li><li>the GitHub scheduler opens execution slots and must not manufacture completion facts;</li><li>every formal execution writes a Runtime Record;</li><li>exactly six statuses are allowed: <code>Running</code>, <code>Completed</code>, <code>Blocked</code>, <code>Failed</code>, <code>Skipped</code>, and <code>Waiting</code>;</li><li>formal publication requires a GitHub commit and Commit Verify;</li><li>a publication without a Runtime Record is not an official runtime output.</li></ul><h2 id="v1-0-release-metadata" tabindex="-1">V1.0 release metadata <a class="header-anchor" href="#v1-0-release-metadata" aria-label="Permalink to &quot;V1.0 release metadata&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Capability</td><td>Research Runtime Scheduler</td></tr><tr><td>Historical version</td><td>V1.0</td></tr><tr><td>Release date</td><td>2026-08-02</td></tr><tr><td>Timezone</td><td><code>Asia/Shanghai</code></td></tr><tr><td>Digital Researcher at release</td><td>Research Report Production Engine V1.0</td></tr><tr><td>Current Digital Researcher</td><td><a href="./research-report-production-engine-v1.3">Research Report Production Engine V1.3</a></td></tr><tr><td>System of record</td><td>GitHub repository <code>joinwell52-AI/joinwell52</code></td></tr><tr><td>Runtime Record</td><td><code>research/runtime/YYYY/MM/YYYY-MM-DD-runtime.md</code></td></tr></tbody></table><h2 id="the-seven-v1-0-tasks" tabindex="-1">The seven V1.0 tasks <a class="header-anchor" href="#the-seven-v1-0-tasks" aria-label="Permalink to &quot;The seven V1.0 tasks&quot;">​</a></h2><p>V1.0 used seven formal tasks: Engine, Queue, Knowledge, Architecture, Publication, Weekly, and Academic.</p><p>It did not yet contain a separate 15:00 Production shift. Writing, visualization, evidence work, and publication editing therefore had not been organized as an independent afternoon production stage.</p><h2 id="from-v1-0-to-v2-0" tabindex="-1">From V1.0 to V2.0 <a class="header-anchor" href="#from-v1-0-to-v2-0" aria-label="Permalink to &quot;From V1.0 to V2.0&quot;">​</a></h2><p>Scheduler V2.0 adds and clarifies:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>09:00 Engine</span></span>
<span class="line"><span>10:00 Queue + Research Intelligence + three-column decisions</span></span>
<span class="line"><span>11:00 Knowledge</span></span>
<span class="line"><span>Monday 12:00 Architecture</span></span>
<span class="line"><span>15:00 Production → complete Publication Candidate</span></span>
<span class="line"><span>20:00 Publication → GitHub + website + Commit Verify</span></span>
<span class="line"><span>Sunday 20:30 Weekly</span></span>
<span class="line"><span>Wednesday 10:00 Academic</span></span></code></pre></div><p>It also introduces:</p><ul><li>three source-intelligence pipelines;</li><li>separate decisions for three research columns;</li><li>structured work outcomes for every scheduled task;</li><li>the three-column Daily Research Plan;</li><li>Publication Candidate batches;</li><li>an automatically generated Operations Center.</li></ul><h2 id="v1-0-runtime-gate" tabindex="-1">V1.0 Runtime Gate <a class="header-anchor" href="#v1-0-runtime-gate" aria-label="Permalink to &quot;V1.0 Runtime Gate&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Research Runtime</span></span>
<span class="line"><span>→ Runtime Record</span></span>
<span class="line"><span>→ GitHub Commit</span></span>
<span class="line"><span>→ Commit Verify</span></span>
<span class="line"><span>→ Official Publication</span></span></code></pre></div><p>V2.0 extends this gate by making the Production Candidate the formal handoff object between 15:00 and 20:00.</p><h2 id="current-authoritative-implementation" tabindex="-1">Current authoritative implementation <a class="header-anchor" href="#current-authoritative-implementation" aria-label="Permalink to &quot;Current authoritative implementation&quot;">​</a></h2><ul><li><a href="./../runtime/v4">Research Runtime Center V4</a></li><li><a href="./../runtime/research-intelligence">Research Intelligence System V1.0</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/runtime/README.md" target="_blank" rel="noreferrer">Runtime Charter</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/runtime/SCHEDULER.json" target="_blank" rel="noreferrer">Scheduler V2.0 Manifest</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/runtime/WORKER-PROMPTS-V2.md" target="_blank" rel="noreferrer">Worker Contracts V2</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/releases/research-runtime-scheduler-v1.0/RELEASE.md" target="_blank" rel="noreferrer">V1.0 Historical Release Record</a></li></ul>`,20))])}const b=a(o,[["render",c]]);export{g as __pageData,b as default};
